import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        // earliest prefix index for each remainder of the prefix sum
        HashMap<Long, Integer> first = new HashMap<>(2 * n + 2);
        first.put(0L, 0);
        long rem = 0;
        int answer = 0;
        for (int i = 1; i <= n; i++) {
            rem = (rem + nextLong()) % k;
            Integer at = first.get(rem);
            if (at != null) answer = Math.max(answer, i - at);
            else first.put(rem, i);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, k := readInt(), readInt()
	// earliest prefix index for each remainder of the prefix sum
	first := make(map[int]int, n+1)
	first[0] = 0
	rem, answer := 0, 0
	for i := 1; i <= n; i++ {
		rem = (rem + readInt()) % k
		if at, ok := first[rem]; ok {
			answer = max(answer, i-at)
		} else {
			first[rem] = i
		}
	}
	fmt.Println(answer)
}
